  function paymentProviderLabel(provider){return provider==="NICEPAY"?"NICEPAY · 나이스페이먼츠":provider==="ONSITE"?"매장 결제":provider||"결제 정보 없음";}
  function editableReservationStatuses(row,payment){
    const all=Object.keys(reservationLabels);
    if(!payment.nice)return all;
    let allowed=[];
    if(["READY","VERIFYING"].includes(payment.status)&&row.status==="PENDING_PAYMENT")allowed=["PENDING_PAYMENT"];
    else if(payment.status==="PAID"&&["CONFIRMED","COMPLETED","CANCEL_REQUESTED","NO_SHOW"].includes(row.status))allowed=["CONFIRMED","COMPLETED","CANCEL_REQUESTED","NO_SHOW"];
    else if(["FAILED","EXPIRED","REFUNDED"].includes(payment.status)&&row.status==="CANCELED")allowed=["CANCELED"];
    else allowed=[row.status];
    return [...new Set(allowed.filter(Boolean))];
  }
  function paymentSummary(row){const payment=paymentInfo(row),needsReview=payment.failureCode==="NICEPAY_STATUS_REVIEW",failed=["FAILED","EXPIRED","UNKNOWN"].includes(payment.status)||needsReview,verifying=["VERIFYING","UNKNOWN","CANCEL_PENDING"].includes(payment.status),refunded=["REFUNDED","PARTIALLY_REFUNDED"].includes(payment.status),card=[payment.cardName,payment.cardNumber].filter(Boolean).join(" · "),failureCode=payment.failureCode||(failed&&payment.resultCode!=="0000"?payment.resultCode:""),hasFailure=failed&&Boolean(payment.failureMessage||failureCode);return `<section class="admin-payment-summary ${failed?"is-failed":verifying?"is-verifying":""}"><header><div><span>결제</span><strong>${h(paymentProviderLabel(payment.provider))}</strong></div><b>${h(payment.label)}</b></header>${payment.approvedAt||card||payment.transactionId?`<dl>${payment.approvedAt?`<div><dt>승인 시각</dt><dd>${h(formatDateTime(payment.approvedAt))}</dd></div>`:""}${card?`<div><dt>결제 카드</dt><dd>${h(card)}</dd></div>`:""}${payment.transactionId?`<div class="wide"><dt>거래번호</dt><dd><code>${h(payment.transactionId)}</code></dd></div>`:""}</dl>`:""}${payment.status==="VERIFYING"?`<p>승인 결과를 확인하고 있습니다. 확인이 끝나면 예약과 결제 상태가 자동으로 바뀝니다.</p>`:""}${hasFailure?`<p class="admin-payment-failure"><strong>${needsReview?"결제사 상태 확인 필요":h(payment.label)}</strong>${payment.failureMessage?h(payment.failureMessage):"결제사 결과 코드를 확인해 주세요."}${failureCode?` · 코드 ${h(failureCode)}`:""}</p>`:""}${refunded&&payment.failureMessage&&!needsReview?`<p class="admin-payment-note">${h(payment.failureMessage)}</p>`:""}${payment.receiptUrl?`<a href="${h(payment.receiptUrl)}" target="_blank" rel="noopener noreferrer">카드 매출전표 보기</a>`:""}</section>`;}

  async function api(path,options={},admin=false,timeout=15000){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),timeout);try{const response=await fetch(`${API}${path}`,{...options,cache:"no-store",signal:controller.signal,headers:{apikey:PUBLISHABLE_KEY,"Content-Type":"application/json",...(admin&&state.token?{Authorization:`Bearer ${state.token}`}:{}) ,...(options.headers||{})}});const data=await response.json().catch(()=>({}));if(!response.ok){const error=new Error(data.error||"요청을 처리하지 못했습니다.");error.status=response.status;throw error;}return data;}catch(error){if(error?.name==="AbortError")throw new Error("응답이 늦어지고 있습니다. 잠시 후 다시 시도해 주세요.");throw error;}finally{clearTimeout(timer);}}
