  async function loadDashboard(){if(!state.token){loginPage();return;}ROOT.innerHTML=`<main class="admin-loading-page"><div><i></i><strong>운영 데이터를 불러오고 있습니다.</strong></div></main>`;try{state.data=await api("/admin/dashboard",{},true);if(!state.user)state.user={displayName:"서면점 운영자"};if(!state.data.themes?.some(x=>x.id===state.selectedTheme))state.selectedTheme=state.data.themes?.[0]?.id||"A";if(!state.data.themes?.some(x=>x.id===state.scheduleTheme))state.scheduleTheme=state.data.themes?.[0]?.id||"A";renderCurrent();}catch(error){if(error.status===401){clearSession();loginPage("로그인이 만료되었습니다. 암호키를 다시 입력해 주세요.");}else{ROOT.innerHTML=`<main class="admin-fatal"><div><h1>운영 데이터를 불러오지 못했습니다.</h1><p>${h(error.message)}</p><button type="button">다시 시도</button></div></main>`;ROOT.querySelector("button")?.addEventListener("click",loadDashboard);}}}
